        return nivelClube == NivelClube.OURO && subtotalProdutos.compareTo(LIMITE_BRINDE) > 0;
    }

    private BigDecimal arredondar(BigDecimal valor) {
        return valor.setScale(2, RoundingMode.HALF_EVEN);
    }

