        if (request.getCupom() != null && !request.getCupom().isEmpty()) {
            if (Cupom.fromCodigo(request.getCupom()) == null) {
                throw new CheckoutException("CUPOM_INVALIDO");
            }

            BigDecimal subtotal = calcularSubtotalProdutos(request.getItens());
