                if (subtotal.compareTo(new BigDecimal("300.00")) < 0) {
                    throw new CheckoutException("CUPOM_NAO_APLICAVEL");
                }
            }
        }
    }

    private void validarFormaPagamento(CheckoutRequest request) throws CheckoutException {
