        if ("PIX".equals(formaPagamento) || "BOLETO".equals(formaPagamento)) {
            if (parcelas != 1) {
                throw new CheckoutException("PARCELAMENTO_INVALIDO");
            }
        } else if ("CARTAO".equals(formaPagamento)) {
            if (parcelas < 1 || parcelas > 12) {
                throw new CheckoutException("PARCELAMENTO_INVALIDO");
            }
        }
